\set ON_ERROR_STOP on
DO $$ BEGIN
 IF current_database() NOT LIKE 'aifrogi_answer_review_%' THEN RAISE EXCEPTION 'SYNTHETIC_TEST_DATABASE_REQUIRED'; END IF;
END $$;
UPDATE "KnowledgeEntry" SET status='PUBLISHED',"revisionState"='SEALED',"sealManifestHash"='entry-seal',"sealPolicyVersion"='v1',"sealedAt"=clock_timestamp(),"sealedBy"='publisher',"updatedAt"=clock_timestamp() WHERE id='delivery-entry';
UPDATE "KnowledgePublication" SET state='SEALED',"sealedAt"=clock_timestamp(),"membershipClosedAt"=clock_timestamp() WHERE id='delivery-publication';


UPDATE "KnowledgeReleaseArtifact" SET state='ACTIVE',"sealedAt"=clock_timestamp(),"membershipClosedAt"=clock_timestamp() WHERE id='delivery-release';

